@@ -0,0 +1,139 @@
+// U3's routes and the `retry-ladder` fixture trail (tests/web/fixtures/trails/retry-ladder/README.md), on top of U1's
+// and U0b's helpers for the built app (vite preview on DOCKET_APP_PORT): serving trace data, themes, widths, axe and
+// the rule and commit links. U3 builds the loop, verdict and finding screens, the node page's attempts region, the
+// plan page's investigation body and the about page's provenance labels (docs/ui/derived/U3/derived.json).
+import { expect } from '@playwright/test';
+import type { Locator, Page } from '@playwright/test';
+import { compileFixture } from '../../U0b/support/trail';
+import type { CompiledTrail } from '../../U0b/support/trail';
+import { openOnFixture, region } from '../../U1/support/app';
+
+export { openOnFixture, region };
+export { REPO, auditEverywhere, commitHref, compileRules, shaOf, short, snapshotOf } from '../../U1/support/app';
+export type { CompiledTrail } from '../../U1/support/app';
+export { setTheme, viewports } from '../../U0b/support/app';
+
+/** U3's routes (hash routing). */
+export const route = {
+  about: '/#/about',
+  plan: (plan: string): string => `/#/plans/${plan}`,
+  node: (plan: string, node: string): string => `/#/plans/${plan}/${node}`,
+  loop: (plan: string, node: string): string => `/#/plans/${plan}/${node}/loop`,
+  verdict: (plan: string, node: string, round: string, agent: string): string => `/#/plans/${plan}/${node}/verdicts/${round}/${agent}`,
+  findings: (plan: string, node: string, round: string): string => `/#/plans/${plan}/${node}/findings/${round}`,
+};
+
+/** The fixture U3's behaviour tests run on: build/F1 over three attempts, with inv-001 before the third. */
+export const RETRY = 'retry-ladder';
+
+/** Compiles the `retry-ladder` fixture once for a spec file. */
+export function compileRetry(): CompiledTrail {
+  return compileFixture(RETRY);
+}
+
+/** The regions U3 builds, by their data-region slugs (docs/ui/derived/U3/<screen>/screen.json). */
+export const LADDER = 'attempt-ladder';
+export const TIMELINE = 'gate-timeline';
+export const SUMMARY = 'verdict-summary';
+export const VERDICT_FINDINGS = 'findings';
+export const RAW_JSON = 'raw-json';
+export const FINDINGS = 'findings';
+export const FIXED_BY = 'fixed-by';
+export const ATTEMPTS = 'attempts';
+export const INVESTIGATION = 'investigation-body-inv-plans-only';
+export const PROVENANCE = 'provenance-labels';
+
+/** The file on GitHub at a SHA, at a line: where a verdict finding's file:line links. */
+export function blobHref(repo: string, sha: string, path: string, line: number): string {
+  return `${repo}/blob/${sha}/${path}#L${line}`;
+}
+
+/**
+ * A gate or state event drawn by the kit's gate-row, by its accessible name: "<attempt>·<line> <event>: <result>",
+ * the result one of "Gate held", "Gate failed", "Failed as expected", "Waived" or, for a state event, "State change".
+ */
+export function gateRow(scope: Locator, name: string): Locator {
+  return scope.getByRole('group', { name, exact: true });
+}
+
+/** Every gate and state event drawn in `scope`, as its row's accessible name, in page order. */
+export async function gateRowNames(scope: Locator): Promise<string[]> {
+  return scope
+    .locator('[data-kind="gate"][aria-label], [data-kind="state"][aria-label]')
+    .evaluateAll((rows) => rows.map((row) => row.getAttribute('aria-label') ?? ''));
+}
+
+/** A term's value in a description list: the <dd> after the <dt> whose whole text is `term`. */
+export function fact(scope: Locator, term: string): Locator {
+  return scope
+    .locator('dt')
+    .filter({ hasText: new RegExp(`^\\s*${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`) })
+    .first()
+    .locator('xpath=following-sibling::dd[1]');
+}
+
+/** One item of a rung spine (the kit's attempt ladder): an attempt's rung, or a branch stepping off the spine. */
+export interface SpineItem {
+  kind: string;
+  /** A rung's label ("Attempt 2"), or a branch's heading ("Investigation inv-001"). */
+  label: string;
+  /** The status the rung's tag line gives (pass, fail, warn, pending, not-built); null for a branch. */
+  status: string | null;
+  /** The words of the rung's tag ("Failed at gate.stub"); '' for a branch. */
+  tag: string;
+}
+
+/** The rungs and branches of the ladder in `scope`, in page order. */
+export async function spineItems(scope: Locator): Promise<SpineItem[]> {
+  return scope.locator('li[data-kind="rung"], li[data-kind="branch"]').evaluateAll((items) =>
+    items.map((li) => {
+      const clean = (s: string | null | undefined): string => (s ?? '').replace(/\s+/g, ' ').trim();
+      const kind = li.getAttribute('data-kind') ?? '';
+      if (kind === 'branch') {
+        return { kind, label: clean(li.querySelector('h2, h3, h4, h5, h6')?.textContent), status: null, tag: '' };
+      }
+      const label = document.getElementById(li.getAttribute('aria-labelledby') ?? '');
+      const tag = label?.parentElement?.querySelector('[data-status]') ?? null;
+      return { kind, label: clean(label?.textContent), status: tag?.getAttribute('data-status') ?? null, tag: clean(tag?.textContent) };
+    }),
+  );
+}
+
+/** An attempt's rung in the ladder in `scope`, by its label: "Attempt 2". */
+export function rung(scope: Locator, label: string): Locator {
+  return scope.locator('li[data-kind="rung"]').filter({ has: scope.page().getByText(label, { exact: true }) });
+}
+
+/**
+ * The steps of attempt `n` (the kit's "Steps of attempt <n>" list), opening its "Show the steps of attempt <n>"
+ * control first where the ladder keeps them behind one.
+ */
+export async function stepsOf(scope: Locator, n: number): Promise<Locator> {
+  const show = scope.getByRole('button', { name: `Show the steps of attempt ${n}` });
+  if ((await show.count()) > 0 && (await show.getAttribute('aria-expanded')) === 'false') await show.click();
+  return scope.getByRole('list', { name: `Steps of attempt ${n}`, exact: true });
+}
+
+/** The stage of each step in a steps list, in order: gate, findings, red test, fix commit, verdict, … */
+export async function stagesOf(steps: Locator): Promise<string[]> {
+  await expect(steps, 'the attempt lists its steps').toBeVisible();
+  return steps.locator('xpath=./li').evaluateAll((items) => items.map((li) => li.getAttribute('data-stage') ?? ''));
+}
+
+/** The steps of a steps list at one stage. */
+export function stepsAt(steps: Locator, stage: string): Locator {
+  return steps.locator(`xpath=./li[@data-stage="${stage}"]`);
+}
+
+/** A finding card (the kit's finding-card), by the finding's id as its heading gives it. */
+export function findingCard(scope: Locator, id: string): Locator {
+  return scope.locator('article[data-testable]').filter({ has: scope.page().getByRole('heading', { name: new RegExp(`^${id}\\b`) }) });
+}
+
+/** Opens a route on the compiled fixture and waits until the page's main content has drawn a region. */
+export async function openRegion(page: Page, fixture: CompiledTrail, path: string, slug: string): Promise<Locator> {
+  await openOnFixture(page, fixture, path);
+  const found = region(page, slug);
+  await expect(found, `the page draws its ${slug} region`).toBeVisible();
+  return found;
+}
diff --git a/tests/web/e2e/U3/support/parity.ts b/tests/web/e2e/U3/support/parity.ts
new file mode 100644
index 00000000..b0d1c223
--- /dev/null
+++ b/tests/web/e2e/U3/support/parity.ts
@@ -0,0 +1,131 @@
+// Parity with U3's derived reference (docs/ui/derived/U3/), the built routes served on the design fixture
+// (docs/ui/fixture/), so both sides read the same data. Structure only: the tagged regions in order, the catalogued
+// components in each, the shell, the title and the navigation, and tokens in place of literal colours. The reader is
+// U0b's (tests/web/e2e/U0b/support/reference.ts). A region or nav entry a later node builds (in transit against U3's
+// own derived.json, ../../U0b/support/built.ts) is compared by its place only, so these checks keep holding as later
+// nodes land. Parity tests are the only ones, with reachability, that may pass at the stub.
+import { expect } from '@playwright/test';
+import type { BrowserContext, Page } from '@playwright/test';
+import { serveTrace, setTheme, themes, viewports } from '../../U0b/support/app';
+import { builtAt } from '../../U0b/support/built';
+import { literalColours, readBuilt, readReference as readFromU0b, regionNamed } from '../../U0b/support/reference';
+import type { Structure } from '../../U0b/support/reference';
+import { designFixtureDir } from '../../U0b/support/trail';
+import { route } from './app';
+
+export interface Screen {
+  label: string;
+  screen: string;
+  state: string;
+  path: string;
+}
+
+// Each reference's own data in the design fixture (docs/ui/screens/<screen>/screen.json, its states).
+export const loop: Screen = { label: 'loop page (build/F3)', screen: 'loop', state: 'populated', path: route.loop('build', 'F3') };
+export const loopLong: Screen = { label: 'loop page (build/F1, the most events)', screen: 'loop', state: 'long-content', path: route.loop('build', 'F1') };
+export const loopGitOnly: Screen = { label: 'loop page (build/F0a, git-only)', screen: 'loop', state: 'git-only', path: route.loop('build', 'F0a') };
+export const verdict: Screen = {
+  label: 'verdict page (build/F3 A2.3 reviewer)',
+  screen: 'verdict',
+  state: 'populated',
+  path: route.verdict('build', 'F3', 'A2.3', 'reviewer'),
+};
+export const verdictLong: Screen = {
+  label: 'verdict page (build/F2 A2 reviewer, the most findings)',
+  screen: 'verdict',
+  state: 'long-content',
+  path: route.verdict('build', 'F2', 'A2', 'reviewer'),
+};
+export const finding: Screen = { label: 'finding page (build/F3 A1)', screen: 'finding', state: 'populated', path: route.findings('build', 'F3', 'A1') };
+export const findingLong: Screen = {
+  label: 'finding page (build/F1 D2, the longest round)',
+  screen: 'finding',
+  state: 'long-content',
+  path: route.findings('build', 'F1', 'D2'),
+};
+export const node: Screen = { label: 'node page (build/F3)', screen: 'node', state: 'populated', path: route.node('build', 'F3') };
+export const plan: Screen = { label: 'plan page (build)', screen: 'plan', state: 'populated', path: route.plan('build') };
+export const about: Screen = { label: 'about page', screen: 'about', state: 'populated', path: route.about };
+
+const { regionSettled, settledNav } = builtAt('U3');
+
+/** Reads docs/ui/derived/U3/<screen>/<state>.html. U0b's reader joins docs/ui/derived/U0b with the screen given. */
+function readReference(context: BrowserContext, screen: string, state: string): Promise<Structure> {
+  return readFromU0b(context, `../U3/${screen}`, state);
+}
+
+async function open(page: Page, s: Screen): Promise<void> {
+  await serveTrace(page, designFixtureDir);
+  await setTheme(page, 'light');
+  await page.setViewportSize(viewports[1440]);
+  await page.goto(s.path);
+}
+
+/**
+ * The shell as parity compares it. The title only where the reference's frame names the entity shown: the loop's
+ * variant states keep build/F3's frame. The nav's links and not-built entries are every entry but those in transit.
+ */
+function shellOf(s: Structure, withTitle: boolean): Record<string, unknown> {
+  return {
+    ...(withTitle ? { title: s.title } : {}),
+    shell: s.shell,
+    navLinks: settledNav(s.navLinks),
+    navNotBuilt: settledNav(s.navNotBuilt),
+    navCurrent: s.navCurrent,
+    tabCurrent: s.tabCurrent,
+  };
+}
+
+/** The regions in page order: [slug, req, built] for a settled region, [slug] alone for one a later node builds. */
+function settledOrder(s: Structure, screen: string): (string | boolean)[][] {
+  return s.regions.map((r) => (regionSettled(screen, r.slug) ? [r.slug, r.req.join(' '), r.built] : [r.slug]));
+}
+
+/** The components of each region unbuilt at U3 and still unbuilt at the newest reference. */
+function unbuiltComps(s: Structure, screen: string): [string, string[]][] {
+  return s.regions.filter((r) => !r.built && regionSettled(screen, r.slug)).map((r) => [r.slug, r.comps]);
+}
+
+/** Every region of the reference, in its order, with its data-req; the unbuilt ones as the not-built-yet pattern. */
+export async function expectRegionsInOrder(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const built = await readBuilt(page, reference);
+      return { order: settledOrder(built, s.screen), unbuilt: unbuiltComps(built, s.screen) };
+    })
+    .toEqual({ order: settledOrder(reference, s.screen), unbuilt: unbuiltComps(reference, s.screen) });
+}
+
+/** One region of the reference, with its data-req and the catalogued components inside it. */
+export async function expectRegionComponents(page: Page, s: Screen, slug: string): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  const wanted = regionNamed(reference, slug);
+  expect(wanted, `the reference has region ${slug}`).toBeDefined();
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const found = regionNamed(await readBuilt(page, reference), slug);
+      return found ? { req: found.req, comps: found.comps } : null;
+    })
+    .toEqual({ req: wanted?.req, comps: wanted?.comps });
+}
+
+/** The shell's components, the primary nav (links, not-built entries, the current one), the current tab, the title. */
+export async function expectShell(page: Page, s: Screen, withTitle: boolean): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => shellOf(await readBuilt(page, reference), withTitle)).toEqual(shellOf(reference, withTitle));
+}
+
+/** No colour on the page from a literal: the screen's styles, inline styles and SVG paint use tokens only. */
+export async function expectTokensOnly(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => (await readBuilt(page, reference)).regions.length).toBe(reference.regions.length);
+  for (const theme of themes) {
+    await setTheme(page, theme);
+    expect.soft(await page.evaluate(literalColours), `literal colours, ${theme}`).toEqual([]);
+  }
+}
