+}, SLOW);
+afterAll(() => trail?.cleanup());
+
+const A2_FINGERPRINT = '7c2e9a41d06b38f5e1a4c9d27b80f63e5a1d4c98';
+const A3_FINGERPRINT = 'e05b7d3c9a1f28e64b0c7d19a3f5e82c46b1d07a';
