+    expect(r.error, thrown(r)).toBeUndefined();
+    const i1 = findingOf(r, 'A1', 'I1');
+    expect([i1?.rule ?? null, i1?.layer ?? null, i1?.files ?? null]).toEqual(['SELL-2', 'api', ['src/sell.txt', 'tests/web/e2e/F1/sell.spec.ts']]);
