+
+/** A marker's name ("Symptom", "Cause", "Fix direction") where a colon, or a qualifier and a colon, follows it. */
+const MARKER_NAME = /\b(?:Symptom|Cause|Fix direction)(?=\s*(?:\([^)]*\))?\s*:)/g;
+
